package io.github.jesterportfolio.hearth.survival;

import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import org.bukkit.*;
import org.bukkit.plugin.java.JavaPlugin;
import com.sk89q.worldguard.WorldGuard;
import com.sk89q.worldedit.bukkit.BukkitAdapter;
import io.github.jesterportfolio.hearth.administration.RuntimeLease;

/** 바닐라 생성기를 사용하는 고정 3월드. 최초 준비 이후 누락/변경은 HOLD입니다. */
public final class SurvivalWorlds implements AutoCloseable {
    private final JavaPlugin plugin;private final SurvivalSettings settings;private final Map<SurvivalWorld,World> worlds=new EnumMap<>(SurvivalWorld.class);private final Map<SurvivalWorld,Location> entries=new EnumMap<>(SurvivalWorld.class);private final List<Chunk> tickets=new ArrayList<>();private boolean closed;
    public SurvivalWorlds(JavaPlugin plugin,SurvivalSettings settings){this.plugin=plugin;this.settings=settings;}
    public CompletionStage<Void> prepare()throws Exception {
        Path data=plugin.getDataFolder().toPath().toAbsolutePath();if(!data.equals(data.toRealPath())||Files.exists(data.resolve("economy-world.properties"),LinkOption.NOFOLLOW_LINKS))throw new IllegalStateException("SURVIVAL_LEGACY_OR_PATH");
        Path registry=data.resolve("survival-worlds.properties"),pending=data.resolve("survival-preparation.pending");boolean existing=Files.exists(registry,LinkOption.NOFOLLOW_LINKS);if(Files.exists(pending,LinkOption.NOFOLLOW_LINKS)||!existing&&!settings.allowCreate())throw new IllegalStateException("SURVIVAL_PREPARATION_REQUIRED");
        var recorded=existing?WorldRegistry.read(registry,settings):Map.<SurvivalWorld,WorldRegistry.Entry>of();
        // 모든 경로를 검사한 뒤 생성/로드합니다. 기존 custom 데이터의 암묵적 채택은 하지 않습니다.
        Path level=Bukkit.getServer().getLevelDirectory().toRealPath();
        if(!existing){var players=level.resolve("playerdata");if(Files.isDirectory(players))try(var files=Files.list(players)){if(files.anyMatch(f->f.getFileName().toString().endsWith(".dat")))throw new IllegalStateException("SURVIVAL_EXISTING_PLAYER_DATA_REQUIRES_REVIEW");}}

        for(var role:SurvivalWorld.values()){var def=settings.worlds().get(role);var key=Objects.requireNonNull(NamespacedKey.fromString(def.key()));var path=level.resolve("dimensions").resolve(key.getNamespace()).resolve(key.getKey());var loaded=Bukkit.getWorld(key);for(Path parent=path;parent!=null&&!parent.equals(level);parent=parent.getParent())if(Files.isSymbolicLink(parent))throw new IllegalStateException("SURVIVAL_WORLD_PATH");
            if(existing){var expected=recorded.get(role);if(!path.equals(path.toRealPath())||!Files.isRegularFile(path.resolve("data/paper/metadata.dat"),LinkOption.NOFOLLOW_LINKS)||!metadataUuid(path.resolve("data/paper/metadata.dat")).equals(expected.uuid())||loaded!=null&&!loaded.getUID().equals(expected.uuid()))throw new IllegalStateException("SURVIVAL_STORED_WORLD_MISMATCH");}
            else if(loaded==null&&Files.exists(path,LinkOption.NOFOLLOW_LINKS)||loaded!=null&&!key.getNamespace().equals("minecraft"))throw new IllegalStateException("SURVIVAL_UNKNOWN_WORLD");
        }
        var lease=existing?null:RuntimeLease.acquire(pending,"Hearth vanilla initial preparation v1\n").orElseThrow();var completion=new CompletableFuture<Void>();
        try{for(var role:SurvivalWorld.values()){var def=settings.worlds().get(role);var key=Objects.requireNonNull(NamespacedKey.fromString(def.key()));var world=Bukkit.getWorld(key);if(world==null){var creator=WorldCreator.ofKey(key).environment(World.Environment.valueOf(def.environment())).type(WorldType.valueOf(def.terrain()));if(def.seed()!=null)creator.seed(def.seed());world=Objects.requireNonNull(Bukkit.createWorld(creator));}if(!world.getEnvironment().name().equals(def.environment())||def.seed()!=null&&world.getSeed()!=def.seed()||existing&&(!world.getUID().equals(recorded.get(role).uuid())||world.getSeed()!=recorded.get(role).seed()))throw new IllegalStateException("SURVIVAL_WORLD_IDENTITY");if(WorldGuard.getInstance().getPlatform().getRegionContainer().get(BukkitAdapter.adapt(world))==null)throw new IllegalStateException("SURVIVAL_WORLDGUARD_UNAVAILABLE");worlds.put(role,world);}
            prepareEntry(0,existing,recorded,()->{try{if(!existing){var rows=new EnumMap<SurvivalWorld,WorldRegistry.Entry>(SurvivalWorld.class);for(var role:SurvivalWorld.values()){var w=worlds.get(role);var p=entries.get(role);w.save(true);rows.put(role,new WorldRegistry.Entry(w.getKey().toString(),w.getUID(),w.getSeed(),settings.worlds().get(role).terrain(),p.getX(),p.getY(),p.getZ()));}WorldRegistry.publish(registry,settings,rows);lease.clean();}completion.complete(null);}catch(Exception failure){completion.completeExceptionally(failure);}},completion);
        }catch(Exception failure){completion.completeExceptionally(failure);}return completion;
    }
    private void prepareEntry(int index,boolean existing,Map<SurvivalWorld,WorldRegistry.Entry> recorded,Runnable finish,CompletableFuture<Void> result){if(closed){result.completeExceptionally(new IllegalStateException("SURVIVAL_CLOSED"));return;}if(index==3){finish.run();return;}var role=SurvivalWorld.values()[index];var w=worlds.get(role);var row=recorded.get(role);var initial=existing?new Location(w,row.x(),row.y(),row.z()):w.getSpawnLocation();int cx=initial.getBlockX()>>4,cz=initial.getBlockZ()>>4;if(existing&&!w.isChunkGenerated(cx,cz)){result.completeExceptionally(new IllegalStateException("SURVIVAL_ENTRY_CHUNK_MISSING"));return;}
        w.getChunkAtAsync(cx,cz,!existing).whenComplete((chunk,error)->Bukkit.getScheduler().runTask(plugin,()->{if(closed||error!=null||chunk==null){result.completeExceptionally(new IllegalStateException("SURVIVAL_ENTRY_LOAD"));return;}try{chunk.addPluginChunkTicket(plugin);tickets.add(chunk);var entry=existing?initial:findSafe(w,initial);if(!safe(entry))throw new IllegalStateException("SURVIVAL_ENTRY_UNSAFE");entries.put(role,entry);prepareEntry(index+1,existing,recorded,finish,result);}catch(Exception invalid){result.completeExceptionally(invalid);}}));
    }
    private static Location findSafe(World w,Location hint){int cx=hint.getBlockX()>>4,cz=hint.getBlockZ()>>4;for(int n=0;n<256;n++){int x=(cx<<4)+((hint.getBlockX()+n)%16+16)%16,z=(cz<<4)+((hint.getBlockZ()+n/16)%16+16)%16;int top=w.getEnvironment()==World.Environment.NETHER?Math.min(124,w.getMaxHeight()-2):w.getMaxHeight()-2;for(int y=top;y>w.getMinHeight();y--){var p=new Location(w,x+.5,y,z+.5);if(safe(p))return p;}}throw new IllegalStateException("SURVIVAL_NO_SAFE_ENTRY_IN_SPAWN_CHUNK");}
    public static boolean safe(Location p){var w=p.getWorld();if(w==null||p.getY()<=w.getMinHeight()||p.getY()+1>=w.getMaxHeight()||!w.getWorldBorder().isInside(p)||!w.isChunkLoaded(p.getBlockX()>>4,p.getBlockZ()>>4))return false;var floor=w.getBlockAt(p.getBlockX(),p.getBlockY()-1,p.getBlockZ());var feet=w.getBlockAt(p.getBlockX(),p.getBlockY(),p.getBlockZ());var head=w.getBlockAt(p.getBlockX(),p.getBlockY()+1,p.getBlockZ());return !feet.isLiquid()&&!head.isLiquid()&&io.github.jesterportfolio.hearth.combat.CombatPlayers.safeCells(floor.getType().name(),feet.getType().name(),head.getType().name(),floor.getType().isSolid(),feet.isPassable(),head.isPassable());}
    public static UUID metadataUuid(Path file)throws Exception{if(!file.equals(file.toRealPath())||Files.size(file)>65536)throw new IllegalStateException("SURVIVAL_METADATA_PATH");byte[] bytes=Files.readAllBytes(file);if(bytes.length>1&&(bytes[0]&255)==31&&(bytes[1]&255)==139)try(var in=new java.util.zip.GZIPInputStream(new java.io.ByteArrayInputStream(bytes))){bytes=in.readNBytes(65537);}if(bytes.length>65536)throw new IllegalStateException("SURVIVAL_METADATA_LIMIT");byte[] tag={11,0,4,117,117,105,100,0,0,0,4};int at=-1;for(int i=0;i<=bytes.length-tag.length-16;i++){boolean match=true;for(int j=0;j<tag.length;j++)if(bytes[i+j]!=tag[j]){match=false;break;}if(match){if(at!=-1)throw new IllegalStateException("SURVIVAL_METADATA_UUID");at=i+tag.length;}}if(at<0)throw new IllegalStateException("SURVIVAL_METADATA_UUID");var buffer=java.nio.ByteBuffer.wrap(bytes,at,16);return new UUID(buffer.getLong(),buffer.getLong());}
    public Location entry(SurvivalWorld role){if(closed)throw new IllegalStateException("SURVIVAL_CLOSED");var value=Objects.requireNonNull(entries.get(role)).clone();if(Bukkit.getWorld(value.getWorld().getUID())!=value.getWorld()||!safe(value))throw new IllegalStateException("SURVIVAL_ENTRY_UNSAFE");return value;}
    public SurvivalWorld role(World world){return worlds.entrySet().stream().filter(e->e.getValue()==world).map(Map.Entry::getKey).findFirst().orElse(null);}
    public Map<SurvivalWorld,World> worlds(){return Map.copyOf(worlds);}
    @Override public void close(){closed=true;for(var chunk:tickets)chunk.removePluginChunkTicket(plugin);tickets.clear();}
}
